import{_ as i,c as t,o,aj as r}from"./chunks/framework.B5VMNd4r.js";const c=JSON.parse('{"title":"系列文章规划：《认知偏差手册》","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/user-cognition/contents.md","filePath":"handbook/user-cognition/contents.md","lastUpdated":1783615807000}'),a={name:"handbook/user-cognition/contents.md"};function n(e,l,s,h,u,g){return o(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="系列文章规划-《认知偏差手册》" tabindex="-1">系列文章规划：《认知偏差手册》 <a class="header-anchor" href="#系列文章规划-《认知偏差手册》" aria-label="Permalink to “系列文章规划：《认知偏差手册》”">​</a></h1><blockquote><p>系列名称：认知偏差手册 IP名称：怕浪猫 追更理由：50个认知偏差，深度拆解每一个——帮你看清大脑的谎言，做更清醒的人</p></blockquote><hr><h2 id="第1章-记忆的陷阱——大脑如何偷偷篡改你的过去" tabindex="-1">第1章：记忆的陷阱——大脑如何偷偷篡改你的过去 <a class="header-anchor" href="#第1章-记忆的陷阱——大脑如何偷偷篡改你的过去" aria-label="Permalink to “第1章：记忆的陷阱——大脑如何偷偷篡改你的过去”">​</a></h2><ul><li>1.1 基本归因错误：为什么甩锅总是外部因素</li><li>1.2 光晕效应：第一印象如何以偏概全</li><li>1.3 可得性启发法：越容易想到的，越容易被高估</li><li>1.4 谷歌效应：搜索让我们变得更蠢了吗</li><li>1.5 蔡加尼克效应：未完成的事为何念念不忘</li><li>1.6 宜家效应：为什么你觉得自己做的比买的好</li><li>1.7 虚假记忆：想象如何悄悄变成&quot;真实记忆&quot;</li><li>1.8 隐记忆：真实记忆为何被误认为想象</li><li><strong>互动钩子</strong>：你有没有过&quot;明明没经历过，却感觉很熟悉&quot;的经历？</li><li><strong>收藏触发点</strong>：记忆偏差完整对照表 + 应对策略清单</li><li><strong>下章预告</strong>：下一章聊&quot;社交中的偏差&quot;——为什么你总觉得别人比你更自私？</li></ul><hr><h2 id="第2章-社交的幻象——你以为的社交直觉-其实全是套路" tabindex="-1">第2章：社交的幻象——你以为的社交直觉，其实全是套路 <a class="header-anchor" href="#第2章-社交的幻象——你以为的社交直觉-其实全是套路" aria-label="Permalink to “第2章：社交的幻象——你以为的社交直觉，其实全是套路”">​</a></h2><ul><li>2.1 自利性偏差：成功是我的，失败是环境的问题</li><li>2.2 道德运气：胜利者光环与失败者污名</li><li>2.3 防卫性归因：为什么我们总是替熟人开脱</li><li>2.4 邓宁-克鲁格效应：越无知的人，越觉得自己了不起</li><li>2.5 确认偏差：每个人都在寻找能证明自己对的证据</li><li>2.6 衰落主义：为什么总觉得&quot;过去比现在好&quot;</li><li>2.7 框架效应：换个说法，结论完全不同</li><li>2.8 幸存者偏差：为什么成功故事总是讲幸存者的</li><li>2.9 本·富兰克林效应：帮人一次，反而更喜欢他</li><li>2.10 旁观者效应：围观的人越多，受害者越危险</li><li>2.11 可受暗示性：暗示如何制造&quot;假记忆&quot;</li><li>2.12 集群错觉：随机事件中看出根本不存在的规律</li><li><strong>互动钩子</strong>：你在生活中有没有遇到过&quot;我觉得对方应该这样做&quot;的道德绑架？</li><li><strong>收藏触发点</strong>：12个社交偏差速查表 + 日常场景对照</li><li><strong>下章预告</strong>：学习偏差——锚定效应、刻板印象、时间扭曲……学习路上99%的弯路都是大脑在作怪</li></ul><hr><h2 id="第3章-学习的迷宫——大脑在学习路上埋了多少坑" tabindex="-1">第3章：学习的迷宫——大脑在学习路上埋了多少坑 <a class="header-anchor" href="#第3章-学习的迷宫——大脑在学习路上埋了多少坑" aria-label="Permalink to “第3章：学习的迷宫——大脑在学习路上埋了多少坑”">​</a></h2><ul><li>3.1 内群体偏见：圈子认同感如何扭曲判断</li><li>3.2 错误共识：你的观点其实没有想象中那么多人认同</li><li>3.3 公正世界谬误：受害者有罪论的心理学根源</li><li>3.4 锚定效应：第一个数字如何永久绑架你的判断</li><li>3.5 逆火效应：越纠正，越坚信——为什么辩论让人更固执</li><li>3.6 维持现状偏见：为什么改变总是那么难</li><li>3.7 刻板印象：没有信息时，大脑如何&quot;脑补&quot;陌生人</li><li>3.8 时间感知扭曲：创伤、药物与体力消耗如何改变你对时间的感知</li><li>3.9 自行车棚效应：为什么人们总在琐事上争论不休</li><li><strong>互动钩子</strong>：你有没有过&quot;明知道该改变，就是迈不出第一步&quot;的经历？</li><li><strong>收藏触发点</strong>：9大学习偏差应对指南 + 自测清单</li><li><strong>下章预告</strong>：信仰偏差——权威、安慰剂、第三人效应……你的信念有多少是被操纵的？</li></ul><hr><h2 id="第4章-信仰的牢笼——你的信念到底有多脆弱" tabindex="-1">第4章：信仰的牢笼——你的信念到底有多脆弱 <a class="header-anchor" href="#第4章-信仰的牢笼——你的信念到底有多脆弱" aria-label="Permalink to “第4章：信仰的牢笼——你的信念到底有多脆弱”">​</a></h2><ul><li>4.1 从众效应：真理为什么会随大流</li><li>4.2 知识的诅咒：懂了之后，再也看不懂&quot;不懂&quot;的样子</li><li>4.3 朴素实在论：我看到的就是真相，别人的都是偏见</li><li>4.4 自动化偏差：过度依赖系统如何毁掉你的判断</li><li>4.5 第三人效应：为什么你觉得别人比自己更容易被洗脑</li><li>4.6 信仰偏见：用可信度代替逻辑，好观点也会变成坏论证</li><li>4.7 沉没成本谬误：不愿放手，是人性最大的弱点之一</li><li>4.8 外团体同质性效应：圈外人看起来都一样，圈内人各不一样</li><li>4.9 权威偏见：对权威的盲从，是如何一步步形成的</li><li>4.10 安慰剂效应：信念本身就是一种&quot;药&quot;</li><li>4.11 悲观主义偏差：高估坏结果的概率</li><li>4.12 乐观主义偏差：低估坏结果的可能性</li><li><strong>互动钩子</strong>：你有没有过&quot;明明逻辑不支持，但就是相信&quot;的时候？</li><li><strong>收藏触发点</strong>：12个信仰偏差完整清单 + 识别三步法</li><li><strong>下章预告</strong>：金钱偏差——投资决策、消费陷阱、风险判断……钱上的认知偏差，可能是最让你亏钱的敌人</li></ul><hr><h2 id="第5章-金钱的盲区——关于钱-大脑撒过的那些谎" tabindex="-1">第5章：金钱的盲区——关于钱，大脑撒过的那些谎 <a class="header-anchor" href="#第5章-金钱的盲区——关于钱-大脑撒过的那些谎" aria-label="Permalink to “第5章：金钱的盲区——关于钱，大脑撒过的那些谎”">​</a></h2><ul><li>5.1 团体迷思：会议室里最危险的一种声音——共识</li><li>5.2 聚光灯效应：没有那么多人真正在意你</li><li>5.3 幼稚的愤世嫉俗：过度解读他人动机的陷阱</li><li>5.4 效用层叠：一个信念如何在社会中滚雪球</li><li>5.5 零风险偏好：为什么人们宁可少赚也不愿冒险</li><li>5.6 赌徒谬误：连抛10次正面，第11次更可能是反面？</li><li><strong>互动钩子</strong>：你在投资或消费上有没有被&quot;直觉&quot;坑过的经历？</li><li><strong>收藏触发点</strong>：6大金钱偏差决策检查清单 + 理性思维工具</li><li><strong>下章预告</strong>：最后一章——财富/认知综合篇：巴纳姆效应、逆反抗拒、盲点偏见……以及如何真正开始训练自己的认知</li></ul><hr><h2 id="第6章-认知的觉醒——认识你自己-从认识这50个偏差开始" tabindex="-1">第6章：认知的觉醒——认识你自己，从认识这50个偏差开始 <a class="header-anchor" href="#第6章-认知的觉醒——认识你自己-从认识这50个偏差开始" aria-label="Permalink to “第6章：认知的觉醒——认识你自己，从认识这50个偏差开始”">​</a></h2><ul><li>6.1 巴纳姆效应：星座、性格测试为什么那么准？因为说的都是你自己套上去的</li><li>6.2 逆反抗拒：让你往东，你偏往西——自由被威胁时的本能反抗</li><li>6.3 盲点偏见：最难察觉的偏差——承认别人有偏见，却看不见自己的</li><li>6.4 认知偏差的完整地图：50个偏差全景图与相互关联</li><li>6.5 实战训练：如何在日常生活中识别并对抗认知偏差</li><li>6.6 总结与行动清单：成为更清醒的人，从今天开始</li><li><strong>互动钩子</strong>：你现在能说出几个自己的认知盲区？评论区等你的答案</li><li><strong>收藏触发点</strong>：认知偏差完整对照总表 + 30天训练计划</li><li><strong>追更引导</strong>：系列完结，但成长没有终点——关注怕浪猫，持续更新更多认知升级内容</li></ul>',20)])])}const q=i(a,[["render",n]]);export{c as __pageData,q as default};
